var ids=new IdGeneratorService(db);var now=DebtOptions.Today;var month=new DateTime(now.Year,now.Month,1);var suffix=Guid.NewGuid().ToString("N")[..7];var parent="NP"+suffix;var student="NS"+suffix;var other="NX"+suffix;
