var debts=new List<Debt>();foreach(int offset in new[]{-1,0,1}){var d=new Debt{debtId=await ids.GenerateIdAsync("DBT"),userId=parent,debtName="Audit debt "+offset,originalAmount=100,outstandingAmount=100,dueDate=now.AddDays(offset)};debts.Add(d);db.Debts.Add(d);}
var attempts=new List<SavingsAutomaticAttempt>();foreach(var status in new[]{"Saved","CoveredByExtra","InsufficientFunds","MissedOffline"}){var goal=await ids.GenerateIdAsync("SVG");db.SavingsGoals.Add(new(){SavingsGoalId=goal,UserId=parent,GoalName="Audit "+status,TargetAmount=100,TargetDate=now.AddMonths(2)});var attempt=new SavingsAutomaticAttempt{SavingsGoalId=goal,DueDate=now,PlannedAmount=10,Amount=status=="Saved"?10:0,CreditApplied=status=="CoveredByExtra"?10:0,Status=status,ProcessedAtUtc=DateTime.UtcNow};attempts.Add(attempt);db.SavingsAutomaticAttempts.Add(attempt);}
await db.SaveChangesAsync();db.ChangeTracker.Clear();
var mail=new AuditMail();var requestMail=new AuditRequests();var notices=new NotificationService(db);var email=new NotificationEmailService(db,notices,mail,NullLogger<NotificationEmailService>.Instance);var links=new MonitoringLinkService(db,ids,requestMail,NullLogger<MonitoringLinkService>.Instance);var health=new FinancialHealthService(db);var personal=new PersonalNotificationService(db,ids,health);var monitoring=new MonitoringAlertService(db,ids,links,health,email);var reminders=new RoutineBillReminderService(db,ids,email,new ConfigurationBuilder().Build());
await personal.RefreshAsync(parent,now);await reminders.RefreshAsync(parent,now,deliverEmail:false);await monitoring.RefreshAsync(parent,now,deliverEmail:false);db.ChangeTracker.Clear();
foreach(var type in new[]{"PersonalBudgetOverspending","PersonalLowHealth","BudgetOverspending","LowFinancialHealth","BillUpcoming","BillDueToday","BillOverdue","DebtReminder","AutomaticSavings"})Check(await notices.Visible(parent).AnyAsync(n=>n.notificationType==type),type+" generated in-app");
