var baseline=await notices.Visible(parent).CountAsync();await personal.RefreshAsync(parent,now);await reminders.RefreshAsync(parent,now,deliverEmail:false);await monitoring.RefreshAsync(parent,now,deliverEmail:false);Check(await notices.Visible(parent).CountAsync()==baseline,"all scanners deduplicate repeated refreshes");Check(mail.Delivered.Count==0,"in-app refresh never sends SMTP");Check(!await notices.Visible(other).AnyAsync(),"account notification history is isolated");
await links.RequestAsync(parent,other+"@example.invalid");await personal.RefreshAsync(other,now);Check(requestMail.Sent==1,"monitoring request email sent through invitation service");Check(await notices.Visible(other).AnyAsync(n=>n.notificationType=="MonitoringInvitation"),"monitoring invitation appears in-app");Check(!await links.CanMonitorAsync(parent,other),"request grants no access before acceptance");
