var preferences=new UserPreferenceService(db);var p=await preferences.GetAsync(other);await preferences.SaveAsync(other,new(){Revision=p.Revision,InvitationEmail=false});db.ChangeTracker.Clear();var requestCalls=requestMail.Sent;await links.RequestAsync(student,other+"@example.invalid");Check(requestMail.Sent==requestCalls,"invitation email opt-out respected");await personal.RefreshAsync(other,now);Check(await notices.Visible(other).CountAsync(n=>n.notificationType=="MonitoringInvitation")==2,"email opt-out retains pending in-app requests");
// Resolve items before queued delivery to detect stale reminders.
var paidBill=bills.Single(b=>b.dueDate==now);var expenseId=await ids.GenerateIdAsync("EXP");db.Expenses.Add(new(){ExpenseId=expenseId,UserId=parent,ExpenseCategoryId=ec,Amount=10,ExpenseDate=now,PaymentMethod="Cash"});db.RoutineBillPayments.Add(new(){paymentId=await ids.GenerateIdAsync("RBP"),billId=paidBill.billId,expenseId=expenseId,dueDate=now,paidDate=now,amount=10,paymentMethod="Cash",billNameSnapshot=paidBill.billName});await db.SaveChangesAsync();Check(!await notices.Visible(parent).AnyAsync(n=>n.routineBillId==paidBill.billId),"paid bill reminder becomes ineligible");
var paidDebt=debts.Single(d=>d.dueDate==now);await db.Debts.Where(d=>d.debtId==paidDebt.debtId).ExecuteUpdateAsync(s=>s.SetProperty(d=>d.status,"Paid").SetProperty(d=>d.outstandingAmount,0));
var failedAttempt=attempts.Single(a=>a.Status=="InsufficientFunds");await db.SavingsAutomaticAttempts.Where(a=>a.SavingsGoalId==failedAttempt.SavingsGoalId).ExecuteUpdateAsync(s=>s.SetProperty(a=>a.Status,"Saved").SetProperty(a=>a.Amount,10));await personal.RefreshAsync(parent,now);db.ChangeTracker.Clear();
for(int i=0;i<12&&await notices.Eligible(parent).AnyAsync(n=>n.emailStatus=="Pending");i++)await email.DeliverPendingAsync(parent);db.ChangeTracker.Clear();
foreach(var text in new[]{"Your budget limit was exceeded","Your financial health needs attention","Budget limit exceeded","Low Financial Health","Bill upcoming","Bill overdue","Debt repayment upcoming","Debt repayment overdue","Automatic savings result"})Check(mail.Delivered.Any(m=>m.Title.Contains(text)),"email delivered: "+text);
Check(!mail.Delivered.Any(m=>m.Message.Contains(paidBill.billName)&&m.Title.StartsWith("Bill ")),"paid bill email suppressed before delivery");Check(!mail.Delivered.Any(m=>m.Message.Contains(paidDebt.debtName)&&m.Title.StartsWith("Debt repayment")),"paid debt email suppressed before delivery");Check(!mail.Delivered.Any(m=>m.Message.Contains("Audit InsufficientFunds")&&m.Title=="Automatic saving needs funds"),"resolved insufficient-funds email suppressed before delivery");
Check(!await notices.Eligible(parent).AnyAsync(n=>n.emailStatus=="Pending"),"eligible notification email queue drains");
var before=mail.Delivered.Count;await email.DeliverPendingAsync(parent);Check(mail.Delivered.Count==before,"delivered messages do not resend on later worker checks");
await links.TransitionAsync(student,linkId,1,"Disconnect");db.ChangeTracker.Clear();Check(await notices.Visible(parent).AnyAsync(n=>n.notificationType=="MonitoringDisconnected"),"disconnection notification persists after consent ends");Check(!await notices.Visible(parent).AnyAsync(n=>n.notificationType=="BudgetOverspending"||n.notificationType=="LowFinancialHealth"),"disconnect hides linked-user financial details");await email.DeliverPendingAsync(parent);Check(mail.Delivered.Any(m=>m.Title=="Parental monitoring disconnected"),"disconnection email delivered");
var unread=await notices.UnreadAsync(parent);Check(unread>0,"unread badge count includes generated alerts");await notices.MarkAllReadAsync(parent);Check(await notices.UnreadAsync(parent)==0,"mark-all-read clears unread count");var one=await notices.Visible(parent).FirstAsync();Check(!await notices.SetReadAsync(other,one.notificationId,false),"other user cannot change notification read state");Check(await notices.SetReadAsync(parent,one.notificationId,false),"owner can mark notification unread");
// Preference changes cancel queues without deleting original history.
var toggle=await preferences.GetAsync(parent);foreach(var type in new[]{"PersonalBudgetOverspending","PersonalLowHealth","DebtReminder","AutomaticSavings","BillUpcoming","BillDueToday","BillOverdue","BudgetOverspending","LowFinancialHealth","MonitoringDisconnected"})db.Notifications.Add(new(){notificationId=await ids.GenerateIdAsync("NTF"),userId=parent,notificationType=type,title="Audit opt-out",message="Test",eventKey=Guid.NewGuid().ToString("N"),createdDateTime=DateTime.UtcNow,emailStatus="Pending"});await db.SaveChangesAsync();
await preferences.SaveAsync(parent,new(){Revision=toggle.Revision,FinancialEmail=false,BillEmail=false,MonitoringEmail=false,MonitoringDisconnectEmail=false});db.ChangeTracker.Clear();Check(!await db.Notifications.AnyAsync(n=>n.userId==parent&&n.title=="Audit opt-out"&&n.emailStatus=="Pending"),"all four email categories cancel queued messages on opt-out");
Check(await notices.Visible(parent).AnyAsync(n=>n.title=="Audit opt-out"),"existing in-app history retained after preference change");
// Every alert category supports email-only delivery independently of in-app visibility.
var channelSettings=await preferences.GetAsync(parent);
await preferences.SaveAsync(parent,new(){Revision=channelSettings.Revision,FinancialInApp=false,FinancialEmail=true,BillInApp=false,BillEmail=true,MonitoringInApp=false,MonitoringEmail=true,MonitoringDisconnectInApp=false,MonitoringDisconnectEmail=true});db.ChangeTracker.Clear();
var newDebt=await ids.GenerateIdAsync("DBT");db.Debts.Add(new(){debtId=newDebt,userId=parent,debtName="Email-only debt",originalAmount=20,outstandingAmount=20,dueDate=now});
var newBill=await ids.GenerateIdAsync("RBL");db.RoutineBills.Add(new(){billId=newBill,userId=parent,expenseCategoryId=ec,billName="Email-only bill",amount=10,dueDate=now,paymentMethod="Cash"});
var renewed=await db.ParentStudentLinks.FindAsync(linkId);renewed!.linkStatus="Active";renewed.acceptedDate=DateTime.UtcNow;renewed.requestVersion=2;await db.SaveChangesAsync();db.ChangeTracker.Clear();
var emailOnlySince=DateTime.UtcNow;await personal.RefreshAsync(parent,now);await reminders.RefreshAsync(parent,now,deliverEmail:false);await monitoring.RefreshAsync(parent,now,deliverEmail:false);await links.TransitionAsync(student,linkId,2,"Disconnect");db.ChangeTracker.Clear();
foreach(var type in new[]{"DebtReminder","BillDueToday","BudgetOverspending","LowFinancialHealth","MonitoringDisconnected"}){
 var generated=await db.Notifications.AsNoTracking().Where(n=>n.userId==parent&&n.notificationType==type&&n.createdDateTime>=emailOnlySince).ToListAsync();
 Check(generated.Count>0&&generated.All(n=>!n.showInApp&&n.emailStatus=="Pending"),"email-only preference respected: "+type);
}
Check(!await notices.Visible(parent).AnyAsync(n=>n.createdDateTime>=emailOnlySince),"email-only alerts never enter unread in-app history");
